import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.CpZKh-tG.js";const u=JSON.parse('{"title":"ADR-076 — /plan ships Mars-only porkchop in v0.7; multi-destination deferred to v0.8","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-076.md","filePath":"adr/ADR-076.md"}'),o={name:"adr/ADR-076.md"};function i(s,e,l,d,p,c){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-076-—-plan-ships-mars-only-porkchop-in-v0-7-multi-destination-deferred-to-v0-8" tabindex="-1">ADR-076 — /plan ships Mars-only porkchop in v0.7; multi-destination deferred to v0.8 <a class="header-anchor" href="#adr-076-—-plan-ships-mars-only-porkchop-in-v0-7-multi-destination-deferred-to-v0-8" aria-label="Permalink to &quot;ADR-076 — /plan ships Mars-only porkchop in v0.7; multi-destination deferred to v0.8&quot;">​</a></h1><blockquote><p>Status · Accepted Date · 2026-06-09 Gates · v0.7 release</p></blockquote><p><strong>Gating sentence</strong>: /plan ships a single-destination (Mars) porkchop on v0.7; the multi-destination expansion (Venus, Mercury, Jupiter/Saturn/Uranus/Neptune/Pluto flyby, Ceres/Vesta/Psyche/Bennu) lands in v0.8 per <a href="./../rfc/RFC-026">RFC-026</a> and <a href="https://github.com/chipi/orrery/issues/312" target="_blank" rel="noreferrer">issue #312</a>.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><code>/plan</code> advertised twelve destinations in the dropdown (mercury, venus, mars, vesta, ceres, psyche, jupiter, saturn, uranus, neptune, pluto, bennu). Only Mars rendered a real porkchop — every other destination loaded an empty grid because <code>static/data/porkchop/</code> only carries a Mars Lambert-grid manifest (see ADR-026 + ADR-028 for the Lambert-grid + outer-catalogue history).</p><p>Users picking Venus or Jupiter saw a blank chart with no signal that the destination wasn&#39;t actually supported. We were promising twelve destinations and delivering one.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>For v0.7 we reduce the dropdown to <strong>Mars only</strong> so the advertised surface matches what we can honestly serve. The <code>FLYBY_ONLY</code> and <code>GRAVITY_ASSIST_CAVEAT_DESTINATIONS</code> constants stay in place as dead code, so the v0.8 re-expansion is a single-line diff to the <code>DESTINATION_IDS</code> array.</p><p>Multi-destination support lands in <strong>v0.8</strong> per RFC-026:</p><ul><li>inner-system landing porkchops for Mercury + Venus (Lambert grid, same shape as Mars)</li><li>gas-giant + ice-giant flyby porkchops (V∞-vs-Tof, no LOI ∆v term)</li><li>belt-target landing porkchops for Vesta, Ceres, Psyche</li><li>single-asteroid flyby porkchop for Bennu (rendezvous shape per ADR-028)</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Honest surface: every option in the dropdown plots a real porkchop in v0.7.</li><li>Small UX regression: users who previously navigated to /plan?dest=jupiter now get redirected to /plan?dest=mars (existing fallback at line 220 of /plan/+page.svelte already handles unknown destinations).</li><li>v0.8 work is well-scoped: the data layer is straightforward (one Lambert / flyby grid per destination), and the UI layer is unchanged. RFC-026 carries the implementation plan; #312 tracks delivery.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>ADR-026 — original Lambert-grid Mars porkchop architecture</li><li>ADR-028 — outer-catalogue + flyby conventions</li><li>RFC-026 — implementation plan for v0.8 multi-destination expansion</li><li>GH issue #312 — v0.8 delivery tracking</li></ul>',14)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
